import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.util.ImageUtil;

public class ImprovedTileIndicatorsOverlay extends Overlay
{
	private static final Color DESTINATION_TILE_SHADOW_COLOR = new Color(0x8D000000, true);

	private final Client client;
	private final ImprovedTileIndicatorsConfig config;

	@Inject
	private ImprovedTileIndicatorsPlugin plugin;

	@Inject
	private PlayerTileMetronomeController playerTileMetronomeController;

	private final BufferedImage ARROW_ICON;

	private LocalPoint lastDestination;
	private LocalPoint lastlastDestination;
	private int spawnGameCycle;
	private int despawnGameCycle;

	@Inject
	private ImprovedTileIndicatorsOverlay(Client client, ImprovedTileIndicatorsConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
        setPriority(0.6f);

		ARROW_ICON = ImageUtil.loadImageResource(ImprovedTileIndicatorsPlugin.class, "arrow.png");
	}

    @Override
    public Dimension render(Graphics2D graphics)
    {
		final Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null) return null;

		final LocalPoint playerPosLocal = localPlayer.getLocalLocation();
		if (playerPosLocal == null) return null;

		final LocalPoint playerMetronomeTileLocal = getPlayerMetronomeTileLocal(localPlayer, playerPosLocal);

        if (config.customDestinationTile())
        {
            if (lastDestination != null && !lastDestination.equals(client.getLocalDestinationLocation()))
            {
                lastlastDestination = lastDestination;
                despawnGameCycle = client.getGameCycle();
            }

            if (lastDestination == null || !lastDestination.equals(client.getLocalDestinationLocation()))
            {
                if (client.getLocalDestinationLocation() != null) spawnGameCycle = client.getGameCycle();
                lastDestination = client.getLocalDestinationLocation();
            }

            switch (config.highlightDestinationStyle())
            {
                case RS3:
                    renderRS3Tile(graphics, lastDestination, config.highlightDestinationColor(), true, true);
                    renderRS3Tile(graphics, lastlastDestination, config.highlightDestinationColor(), false, false);
                    break;
                case RS3_NO_ARROW:
                    renderRS3Tile(graphics, lastDestination, config.highlightDestinationColor(), false, true);
                    renderRS3Tile(graphics, lastlastDestination, config.highlightDestinationColor(), false, false);
                    break;
            }
        }

        if (config.enablePlayerTileMetronome() && playerMetronomeTileLocal != null) renderPlayerMetronomeTile(graphics, playerMetronomeTileLocal);

        if (config.overlaysBelowPlayer() && client.isGpu()) removePlayer(graphics, localPlayer);

        if (config.overlaysBelowNPCs() && client.isGpu())
        {
            plugin.getBelowNpcs().stream()
                .filter(npc -> npc.getLocalLocation() != null)
                .sorted(Comparator.comparingInt(npc -> npc.getLocalLocation().distanceTo(playerPosLocal)))
                .limit(config.maxNPCsDrawn())
                .forEach(npc -> removeNpc(graphics, npc));
        }
        return null;
    }

    private LocalPoint getPlayerMetronomeTileLocal(Player localPlayer, LocalPoint playerPosLocal)
    {
        if (!config.usePlayerTrueTileForMetronome()) return playerPosLocal;

        final WorldPoint playerTrueTile = localPlayer.getWorldLocation();
        return playerTrueTile == null ? null : LocalPoint.fromWorld(client, playerTrueTile);
    }

	private void renderPlayerMetronomeTile(Graphics2D graphics, LocalPoint playerPosLocal)
	{
		final Color tileColor = playerTileMetronomeController.getCurrentPlayerMetronomeColor();

		if (tileColor == null) return;

		renderPlayerMetronomeSquare(graphics, playerPosLocal, tileColor);
	}

	private void renderPlayerMetronomeSquare(Graphics2D graphics, LocalPoint playerPosLocal, Color tileColor)
	{
		final Polygon poly = Perspective.getCanvasTilePoly(client, playerPosLocal);

		if (poly == null) return;

		final Stroke borderStroke = new BasicStroke((float) config.playerTrueTileBorderWidth());
		final Color fillColor = getPlayerTrueTileFillColor(tileColor);

        if (config.playerTrueTileCornersOnly())
        {
            renderPolygonCorners(graphics, poly, tileColor, fillColor, borderStroke, config.playerTrueTileCornerSize());
            return;
        }

        OverlayUtil.renderPolygon(graphics, poly, tileColor, fillColor, borderStroke);
	}

	private Color getPlayerTrueTileFillColor(Color tileColor)
	{
		final Color configuredFillColor = config.playerTrueTileFillColor();

		if (!config.syncPlayerTrueTileFillColor()) return configuredFillColor;

		return new Color(tileColor.getRed(), tileColor.getGreen(), tileColor.getBlue(), configuredFillColor.getAlpha());
	}

	private static void renderPolygonCorners(Graphics2D graphics, Polygon poly, Color color, Color fillColor, Stroke borderStroke, int divisor)
	{
		graphics.setColor(color);
		final Stroke originalStroke = graphics.getStroke();
		graphics.setStroke(borderStroke);

		for (int i = 0; i < poly.npoints; i++)
		{
			final int pointX = poly.xpoints[i];
			final int pointY = poly.ypoints[i];
			final int previousIndex = (i - 1) < 0 ? poly.npoints - 1 : i - 1;
			final int nextIndex = (i + 1) > poly.npoints - 1 ? 0 : i + 1;

			final int nextX = (poly.xpoints[nextIndex] - pointX) / divisor + pointX;
			final int nextY = (poly.ypoints[nextIndex] - pointY) / divisor + pointY;
			final int previousX = (poly.xpoints[previousIndex] - pointX) / divisor + pointX;
			final int previousY = (poly.ypoints[previousIndex] - pointY) / divisor + pointY;

			graphics.drawLine(pointX, pointY, nextX, nextY);
			graphics.drawLine(pointX, pointY, previousX, previousY);
		}

		graphics.setColor(fillColor);
		graphics.fill(poly);
		graphics.setStroke(originalStroke);
	}

    private void renderRS3Tile(final Graphics2D graphics, final LocalPoint dest, final Color color, boolean drawArrow, boolean appearing)
    {
        if (dest == null) return;

		final int plane = client.getTopLevelWorldView().getPlane();

 		final double size = appearing
            ? 0.65 * (Math.min(7.0, client.getGameCycle() - spawnGameCycle) / 7.0)
            : 0.65 * ((7 - (client.getGameCycle() - despawnGameCycle)) / 7.0);

        if (size < 0) return;

        final Polygon poly = getCanvasTargetTileCirclePoly(client, dest, size, plane, 10);
        final Polygon shadow = getCanvasTargetTileCirclePoly(client, dest, size, plane, 0);
        final Point canvasLoc = Perspective.getCanvasImageLocation(client, dest, ARROW_ICON, 150 + (int) (20 * Math.sin(client.getGameCycle() / 10.0)));

        if (poly != null)
        {
            final Stroke originalStroke = graphics.getStroke();
            graphics.setStroke(new BasicStroke((float) config.destinationTileBorderWidth()));
            graphics.setColor(DESTINATION_TILE_SHADOW_COLOR);
            graphics.draw(shadow);
            graphics.setColor(color);
            graphics.draw(poly);
            graphics.setStroke(originalStroke);
        }

        if (canvasLoc != null && drawArrow && shadow != null)
        {
            // TODO: improve scale as you zoom out
            final double imageScale = 0.8 * Math.min(client.get3dZoom() / 500.0, 1);
            graphics.drawImage(ARROW_ICON, (int) (shadow.getBounds().width / 2 + shadow.getBounds().x - ARROW_ICON.getWidth() * imageScale / 2), canvasLoc.getY(), (int) (ARROW_ICON.getWidth() * imageScale), (int) (ARROW_ICON.getHeight() * imageScale), null);
        }
    }

    public static Polygon getCanvasTargetTileCirclePoly(
        @Nonnull Client client,
        @Nonnull LocalPoint localLocation,
        double size,
        int plane,
        int zOffset)
    {
        final int sceneX = localLocation.getSceneX();
        final int sceneY = localLocation.getSceneY();

        if (sceneX < 0 || sceneY < 0 || sceneX >= Perspective.SCENE_SIZE || sceneY >= Perspective.SCENE_SIZE) return null;

        final Polygon poly = new Polygon();
        final int resolution = 64;
        final int height = Perspective.getTileHeight(client, localLocation, plane) - zOffset;

        for (int i = 0; i < resolution; i++)
        {
            final double angle = (double) i / resolution * 2 * Math.PI;
            final double offsetX = Math.cos(angle);
            final double offsetY = Math.sin(angle);
            final int x = (int) (localLocation.getX() + offsetX * Perspective.LOCAL_TILE_SIZE * size);
            final int y = (int) (localLocation.getY() + offsetY * Perspective.LOCAL_TILE_SIZE * size);
            final Point p = Perspective.localToCanvas(client, x, y, height);
            if (p == null) continue;
            poly.addPoint(p.getX(), p.getY());
        }

        return poly;
    }

    private void removePlayer(final Graphics2D graphics, final Player player)
    {
        final int localZ = Perspective.getFootprintTileHeight(client, player.getLocalLocation(), player.getWorldView().getPlane(), player.getFootprintSize()) - player.getAnimationHeightOffset();
        removeActor(graphics, player, localZ);
    }

    private void removeNpc(final Graphics2D graphics, final NPC npc)
    {
        final int localZ = Perspective.getFootprintTileHeight(client, npc.getLocalLocation(), npc.getWorldView().getPlane(), npc.getComposition().getFootprintSize()) - npc.getAnimationHeightOffset();
        removeActor(graphics, npc, localZ);
    }

    private void removeActor(final Graphics2D graphics, final Actor actor, final int localZ)
    {
        final int clipX1 = client.getViewportXOffset();
        final int clipY1 = client.getViewportYOffset();
        final int clipX2 = client.getViewportWidth() + clipX1;
        final int clipY2 = client.getViewportHeight() + clipY1;
        final Object origAA = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);

        final Model model = actor.getModel();
        if (model == null)
        {
            graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, origAA);
            return;
        }

        final int vCount = model.getVerticesCount();
        final float[] x3d = model.getVerticesX();
        final float[] y3d = model.getVerticesY();
        final float[] z3d = model.getVerticesZ();
        final int[] x2d = new int[vCount];
        final int[] y2d = new int[vCount];
        final LocalPoint lp = actor.getLocalLocation();
        final int localX = lp.getX();
        final int localY = lp.getY();
        final int rotation = actor.getCurrentOrientation();

        Perspective.modelToCanvas(client, actor.getWorldView(), vCount, localX, localY, localZ, rotation, x3d, z3d, y3d, x2d, y2d);

        boolean anyVisible = false;
        for (int i = 0; i < vCount; i++)
        {
            final int x = x2d[i];
            final int y = y2d[i];
            final boolean visibleX = x >= clipX1 && x < clipX2;
            final boolean visibleY = y >= clipY1 && y < clipY2;
            anyVisible |= visibleX && visibleY;
        }

        if (!anyVisible) return;

        final int tCount = model.getFaceCount();
        final int[] tx = model.getFaceIndices1();
        final int[] ty = model.getFaceIndices2();
        final int[] tz = model.getFaceIndices3();
        final byte[] triangleTransparencies = model.getFaceTransparencies();
        final Composite originalComposite = graphics.getComposite();

        graphics.setComposite(AlphaComposite.Clear);
        graphics.setColor(Color.WHITE);
        for (int i = 0; i < tCount; i++)
        {
            if (getTriDirection(x2d[tx[i]], y2d[tx[i]], x2d[ty[i]], y2d[ty[i]], x2d[tz[i]], y2d[tz[i]]) >= 0) continue;
            if (triangleTransparencies == null || (triangleTransparencies[i] & 255) < 254)
            {
                final Polygon polygon = new Polygon(
                    new int[] {x2d[tx[i]], x2d[ty[i]], x2d[tz[i]]},
                    new int[] {y2d[tx[i]], y2d[ty[i]], y2d[tz[i]]},
                    3);
                graphics.fill(polygon);
            }
        }

        graphics.setComposite(originalComposite);
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, origAA);
    }

    private int getTriDirection(int x1, int y1, int x2, int y2, int x3, int y3)
    {
        final int x4 = x2 - x1;
        final int y4 = y2 - y1;
        final int x5 = x3 - x1;
        final int y5 = y3 - y1;
        return x4 * y5 - y4 * x5;
    }

}

package io.leikvolle.tileindicators;

import com.google.inject.Provides;
import javax.inject.Inject;

import lombok.AccessLevel;
import lombok.Getter;
import net.runelite.api.*;
import net.runelite.api.events.*;
import java.awt.event.KeyEvent;

import static net.runelite.api.MenuAction.MENU_ACTION_DEPRIORITIZE_OFFSET;

import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;
import net.runelite.client.util.WildcardMatcher;

import java.util.*;

@PluginDescriptor(
		name = "Tile Overlay Indicators",
		configName = "tileoverlayindicatorsplugin",
		description = "Tile overlay for NPCs, and players.",
		tags = {"overlay", "tile", "indicator", "highlight", "draw", "color", "npc", "tick", "metronome", "counter"},
		conflicts = {"Improved Tile Indicators"}
)
public class ImprovedTileIndicatorsPlugin extends Plugin
implements KeyListener
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ImprovedTileIndicatorsOverlay overlay;

	@Inject
	private PlayerTileTickCounterOverlay playerTileTickCounterOverlay;

	@Inject
	private PlayerTileMetronomeController playerTileMetronomeController;

	@Inject ImprovedTileIndicatorsConfig config;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private KeyManager keyManager;

	@Getter(AccessLevel.PACKAGE)
	private final Set<NPC> belowNpcs = new HashSet<>();

	@Getter(AccessLevel.PACKAGE)
	private final Set<NPC> onTopNpcs = new HashSet<>();
	private List<String> belowNPCNames = new ArrayList<>();
	private List<String> onTopNPCNames = new ArrayList<>();
	private List<String> excludedNPCNames = new ArrayList<>();
	private final Set<Integer> excludedNPCIds = new HashSet<>();

	private static final String DRAW_ABOVE = "Draw-Above";
	private static final String DRAW_BELOW = "Draw-Below";
	@Provides
	ImprovedTileIndicatorsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ImprovedTileIndicatorsConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(playerTileTickCounterOverlay);
		keyManager.registerKeyListener(this);
		clientThread.invoke(this::rebuild);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(playerTileTickCounterOverlay);
		keyManager.unregisterKeyListener(this);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		playerTileMetronomeController.onGameTick();
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (config.playerMetronomeSyncHotkey().matches(e)) playerTileMetronomeController.resetSyncState();
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			belowNpcs.clear();
			onTopNpcs.clear();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged configChanged)
	{
		if (!configChanged.getGroup().equals("tileoverlayindicators")) return;

		if (shouldResetMetronomeSync(configChanged.getKey())) playerTileMetronomeController.resetSyncState();

		playerTileMetronomeController.onConfigChanged();
		clientThread.invoke(this::rebuild);
	}

	private boolean shouldResetMetronomeSync(String keyName)
	{
		if ("enablePlayerTileMetronome".equals(keyName)) return config.enablePlayerTileMetronome();

		if ("syncPlayerTrueTileFillColor".equals(keyName)) return config.syncPlayerTrueTileFillColor();

		if ("syncTickCounter1ColorWithTile".equals(keyName)) return config.syncTickCounter1ColorWithTile();

		if ("syncTickCounter2ColorWithTile".equals(keyName)) return config.syncTickCounter2ColorWithTile();

		return false;
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned npcSpawned)
	{
		final NPC npc = npcSpawned.getNpc();
		final String npcName = npc.getName();

		if (npcName == null) return;

		if (excludedMatchesNPC(npc)) return;

		final boolean drawBelow = belowMatchesNPCName(npcName);
		final boolean drawOnTop = onTopMatchesNPCName(npcName);

		if (drawBelow && !drawOnTop) belowNpcs.add(npc);
		if (drawOnTop) onTopNpcs.add(npc);
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned npcDespawned)
	{
		final NPC npc = npcDespawned.getNpc();
		belowNpcs.remove(npc);
		onTopNpcs.remove(npc);
	}


	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		int type = event.getType();

		if (type >= MENU_ACTION_DEPRIORITIZE_OFFSET) type -= MENU_ACTION_DEPRIORITIZE_OFFSET;

		final MenuAction menuAction = MenuAction.of(type);

		if (menuAction == MenuAction.EXAMINE_NPC && client.isKeyPressed(KeyCode.KC_SHIFT) && config.overlaysBelowNPCs())
		{
			final NPC npc = client.getTopLevelWorldView().npcs().byIndex(event.getIdentifier());
			if (npc == null) return;
			final String npcName = getNameForCachedNPC(event.getIdentifier());
			if (npcName == null) return;
			if (excludedMatchesNPC(npc)) return;
			boolean matchesList = onTopNPCNames.stream()
					.filter(highlight -> !highlight.equalsIgnoreCase(npcName))
					.anyMatch(highlight -> WildcardMatcher.matches(highlight, npcName));

			// Only show draw options to npcs not affected by a wildcard entry, as wildcards will not be removed by menu options
			if (!matchesList)
			{
				client.getMenu().createMenuEntry(-1)
					.setOption(onTopNPCNames.stream().anyMatch(npcName::equalsIgnoreCase) ? DRAW_BELOW : DRAW_ABOVE)
					.setTarget(event.getTarget())
					.setIdentifier(event.getIdentifier())
					.setType(MenuAction.RUNELITE)
					.onClick(this::toggleDraw);
			}
		}
	}

	public void toggleDraw(MenuEntry click)
	{
		final String name = getNameForCachedNPC(click.getIdentifier());
		if (name == null) return;
		// this trips a config change which triggers the overlay rebuild
		updateNpcsToDrawAbove(name);
	}

	private void updateNpcsToDrawAbove(String npc)
	{
		final List<String> highlightedNpcs = new ArrayList<>(onTopNPCNames);

		if (!highlightedNpcs.removeIf(npc::equalsIgnoreCase)) highlightedNpcs.add(npc);

		// this triggers the config change event and rebuilds npcs
		config.setTopNPCs(Text.toCSV(highlightedNpcs));
	}

	List<String> getBelowNPCNames()
	{
		final String configNpcs = config.getBelowNPCs();

		if (configNpcs.isEmpty()) return Collections.emptyList();

		return Text.fromCSV(configNpcs);
	}

	List<String> getTopNPCs()
	{
		final String configNpcs = config.getTopNPCs();

		if (configNpcs.isEmpty()) return Collections.emptyList();

		return Text.fromCSV(configNpcs);
	}

	List<String> getExcludedNPCs()
	{
		final String configNpcs = config.getExcludedNPCs();

		if (configNpcs.isEmpty()) return Collections.emptyList();

		return Text.fromCSV(configNpcs);
	}

	void rebuild()
	{
		belowNPCNames = getBelowNPCNames();
		onTopNPCNames = getTopNPCs();
		excludedNPCNames = getExcludedNPCs();
		excludedNPCIds.clear();
		belowNpcs.clear();
		onTopNpcs.clear();

		if (client.getGameState() != GameState.LOGGED_IN && client.getGameState() != GameState.LOADING) return;

		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			final String npcName = npc.getName();

			if (npcName == null) continue;

			if (excludedMatchesNPC(npc)) continue;

			final boolean drawBelow = belowMatchesNPCName(npcName);
			final boolean drawOnTop = onTopMatchesNPCName(npcName);

			if (drawBelow && !drawOnTop) belowNpcs.add(npc);
			if (drawOnTop) onTopNpcs.add(npc);
		}
	}

	private boolean belowMatchesNPCName(String npcName)
	{
		for (String matching : belowNPCNames)
		{
			if (WildcardMatcher.matches(matching, npcName)) return true;
		}

		return false;
	}

	private boolean onTopMatchesNPCName(String npcName)
	{
		for (String matching : onTopNPCNames)
		{
			if (WildcardMatcher.matches(matching, npcName)) return true;
		}

		return false;
	}

	private boolean excludedMatchesNPC(NPC npc)
	{
		final String npcName = npc.getName();

		if (npcName != null && excludedMatchesNPCName(npcName))
		{
			excludedNPCIds.add(npc.getId());
			return true;
		}

		return excludedNPCIds.contains(npc.getId());
	}

	boolean isExcludedNpc(NPC npc)
	{
		return excludedMatchesNPC(npc);
	}

	private boolean excludedMatchesNPCName(String npcName)
	{
		for (String matching : excludedNPCNames)
		{
			final String pattern = matching.trim();

			if (!pattern.isEmpty() && WildcardMatcher.matches(pattern, npcName)) return true;
		}

		return false;
	}

	private String getNameForCachedNPC(int id)
	{
		final NPC npc = client.getTopLevelWorldView().npcs().byIndex(id);

		if (npc == null) return null;

		return npc.getName();
	}

}

package io.leikvolle.tileindicators;

import java.awt.Color;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GameState;

@Singleton
public class PlayerTileMetronomeController
{
	private final ImprovedTileIndicatorsConfig config;
	private final Client client;

	@Getter
	private int playerMetronomeTick;

	@Getter
	private int playerMetronomeColorIndex;

	@Getter
	private Color currentPlayerMetronomeColor = Color.WHITE;

	@Getter
	private int playerTickCounter1;

	@Getter
	private int playerTickCounter2;

	@Inject
	PlayerTileMetronomeController(ImprovedTileIndicatorsConfig config, Client client)
	{
		this.config = config;
		this.client = client;
		resetState();
	}

	void onGameTick()
	{
		if (config == null || client.getGameState() != GameState.LOGGED_IN) return;

		if (!hasAnyActiveFeature())
		{
			resetState();
			return;
		}

		advanceMetronomeState();

		playerTickCounter1 = config.showPlayerTileTickCounter1()
			? advanceCounter(playerTickCounter1, config.playerTileTickCounter1CycleLength())
			: 1;

		playerTickCounter2 = config.showPlayerTileTickCounter2()
			? advanceCounter(playerTickCounter2, config.playerTileTickCounter2CycleLength())
			: 1;
	}

	void onConfigChanged()
	{
		if (!hasAnyActiveFeature())
		{
			resetState();
			return;
		}

		normalizeMetronomeState();

		playerTickCounter1 = config.showPlayerTileTickCounter1()
			? normalizeCounter(playerTickCounter1, config.playerTileTickCounter1CycleLength())
			: 1;

		playerTickCounter2 = config.showPlayerTileTickCounter2()
			? normalizeCounter(playerTickCounter2, config.playerTileTickCounter2CycleLength())
			: 1;
	}

	void resetSyncState()
	{
		resetState();
	}

	boolean isPlayerTileMetronomeEnabled()
	{
		return config.enablePlayerTileMetronome();
	}

	Color getTickCounter1Color()
	{
		return config.syncTickCounter1ColorWithTile()
			? currentPlayerMetronomeColor
			: config.playerTileTickCounter1Color();
	}

	Color getTickCounter2Color()
	{
		return config.syncTickCounter2ColorWithTile()
			? currentPlayerMetronomeColor
			: config.playerTileTickCounter2Color();
	}

	private boolean hasAnyActiveFeature()
	{
		return config.enablePlayerTileMetronome()
			|| config.showPlayerTileTickCounter1()
			|| config.showPlayerTileTickCounter2();
	}

	private boolean shouldRunColorCycle()
	{
		return config.enablePlayerTileMetronome()
			|| (config.showPlayerTileTickCounter1() && config.syncTickCounter1ColorWithTile())
			|| (config.showPlayerTileTickCounter2() && config.syncTickCounter2ColorWithTile());
	}

	private void resetState()
	{
		resetMetronomeState();
		playerTickCounter1 = 1;
		playerTickCounter2 = 1;
	}

	private void resetMetronomeState()
	{
		playerMetronomeTick = 1;
		playerMetronomeColorIndex = 1;
		currentPlayerMetronomeColor = resolveMetronomeColor(1);
	}

	private void advanceMetronomeState()
	{
		if (!shouldRunColorCycle())
		{
			resetMetronomeState();
			return;
		}

		setMetronomeState(advanceCounter(playerMetronomeTick, config.playerMetronomeCycleLength()));
	}

	private void normalizeMetronomeState()
	{
		if (!shouldRunColorCycle())
		{
			resetMetronomeState();
			return;
		}

		setMetronomeState(normalizeCounter(playerMetronomeTick, config.playerMetronomeCycleLength()));
	}

	private void setMetronomeState(int tick)
	{
		playerMetronomeTick = tick;
		playerMetronomeColorIndex = tick;
		currentPlayerMetronomeColor = resolveMetronomeColor(tick);
	}

	private int advanceCounter(int currentValue, int cycleLength)
	{
		return currentValue >= cycleLength ? 1 : currentValue + 1;
	}

	private int normalizeCounter(int currentValue, int cycleLength)
	{
		if (currentValue < 1 || currentValue > cycleLength) return 1;

		return currentValue;
	}

	private Color resolveMetronomeColor(int colorIndex)
	{
		switch (colorIndex)
		{
			case 1:
				return config.playerMetronomeColor1();
			case 2:
				return config.playerMetronomeColor2();
			case 3:
				return config.playerMetronomeColor3();
			case 4:
				return config.playerMetronomeColor4();
			case 5:
				return config.playerMetronomeColor5();
			case 6:
				return config.playerMetronomeColor6();
			case 7:
				return config.playerMetronomeColor7();
			case 8:
				return config.playerMetronomeColor8();
			case 9:
				return config.playerMetronomeColor9();
			case 10:
				return config.playerMetronomeColor10();
			default:
				return config.playerMetronomeColor1();
		}
	}
}

package io.leikvolle.tileindicators;

import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Color;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class PlayerTileTickCounterOverlay extends Overlay
{
	private final Client client;
	private final ImprovedTileIndicatorsConfig config;
	private final PlayerTileMetronomeController controller;

	@Inject
	PlayerTileTickCounterOverlay(Client client, ImprovedTileIndicatorsConfig config, PlayerTileMetronomeController controller)
	{
		this.client = client;
		this.config = config;
		this.controller = controller;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final Player localPlayer = client.getLocalPlayer();

		if (localPlayer == null || config == null || controller == null) return null;

		final Font originalFont = graphics.getFont();

		if (config.showPlayerTileTickCounter1())
		{
			renderTickCounter(
				graphics,
				localPlayer,
				String.valueOf(controller.getPlayerTickCounter1()),
				config.playerTileTicksPosition1(),
				config.playerTileTickXOffset1(),
				config.playerTileTickYOffset1(),
				controller.getTickCounter1Color(),
				config.playerTileTickCounter1FontType(),
				config.playerTileTickCounter1FontSize());
		}

		if (config.showPlayerTileTickCounter2())
		{
			renderTickCounter(
				graphics,
				localPlayer,
				String.valueOf(controller.getPlayerTickCounter2()),
				config.playerTileTicksPosition2(),
				config.playerTileTickXOffset2(),
				config.playerTileTickYOffset2(),
				controller.getTickCounter2Color(),
				config.playerTileTickCounter2FontType(),
				config.playerTileTickCounter2FontSize());
		}

		graphics.setFont(originalFont);

		return null;
	}

	private void renderTickCounter(
		Graphics2D graphics,
		Player player,
		String text,
		TickCounterPosition position,
		int xOffset,
		int yOffset,
		Color color,
		FontType fontType,
		int fontSize)
	{
		graphics.setFont(createCounterFont(fontType, fontSize));
		final Point basePoint = getBasePoint(graphics, player, text, position);

		if (basePoint == null) return;

		final Point renderPoint = new Point(basePoint.getX() + xOffset, basePoint.getY() + yOffset);
		OverlayUtil.renderTextLocation(graphics, renderPoint, text, color);
	}

	private Font createCounterFont(FontType fontType, int fontSize)
	{
		if (fontType == FontType.REGULAR) return FontManager.getRunescapeFont().deriveFont(Font.PLAIN, (float) fontSize);

		return new Font(fontType.toString(), Font.PLAIN, fontSize);
	}

	private Point getBasePoint(
		Graphics2D graphics,
		Player player,
		String text,
		TickCounterPosition position)
	{
		final LocalPoint localLocation = player.getLocalLocation();
		final int plane = player.getWorldView().getPlane();

		if (localLocation == null) return null;

		switch (position)
		{
			case TOP:
				return Perspective.localToCanvas(client, localLocation, plane, 214);

			case CENTERED:
				return Perspective.localToCanvas(client, localLocation, plane, 100);

			case BOTTOM:
				return player.getCanvasTextLocation(graphics, text, 10);

			case DEFAULT:
			default:
				final int height = player.getLogicalHeight() + 20;
				return Perspective.localToCanvas(client, localLocation, plane, height);
		}
	}
}

